  tables: [
    { id: "c7t1", title: "العرف الدولي العالمي والعرف الدولي الإقليمي والثنائي", cols: ["وجه المقارنة", "العرف الدولي العالمي", "العرف الدولي الإقليمي والثنائي"], rows: [
      ["نطاق التطبيق", "جميع أشخاص القانون الدولي المعنيين به", "طائفة محددة تجمعها روابط ومصالح خاصة، بل دولتان فقط"],
      ["المشاركة في التكوين", "يكفي اشتراك عدد كبير يمثل المجتمع الدولي في مجمله، وتفترض موافقة الباقين (قبول ضمني)", "لا يطبق على أي من المعنيين به إلا إذا شارك في تكوين ركنيه"],
      ["طريقة التطبيق وعبء الإثبات", "يطبق تلقائيًا، ومن يدعي عدم تطبيقه عليه يثبت اعتراضه الصريح والمستمر", "لا يطبق تلقائيًا، ومن يتمسك به يثبت وجوده وطابعه الملزم في مواجهة الآخر"],
      ["عمومية السوابق", "شرط لتكوين ركنه المادي", "لا تشترط، لأن جميع المعنيين يجب أن يوافقوا عليه ويساهموا في تكوين ركنيه"],
      ["موقف المادة 1/38(ب)", "هو وحده ما تشير إليه بـ«العادات العامة» المقبولة بمثابة قانون", "لا تتحدث عنه، ومع ذلك وجوده مسلم به في العمل والقضاء الدوليين"],
      ["الأحكام المستشهد بها", "المصايد (1951): قاعدة الأميال العشرة لا تفرض على النرويج المعترضة باستمرار", "حق المرور فوق الإقليم الهندي (1960)، وحق الملجأ (1950)، والمصايد (1951): عرف ثنائي بين المملكة المتحدة والنرويج"],
      ["الطابع الآمر", "قد يكون آمرًا فيسمو سموًا مطلقًا (رأي المؤلف)", "لا يمكن أن يكون آمرًا (المادة 53 من اتفاقيتي فيينا)"]
    ], core: "العالمي يطبق تلقائيًا على جميع المعنيين به على أساس القبول الضمني ولو لم يشاركوا في تكوينه، إلا من اعترض صراحة وباستمرار منذ مراحل تكوينه الأولى؛ والإقليمي أو الثنائي لا يطبق إلا على من شارك في تكوين ركنيه، ويقع عبء إثباته على من يتمسك به.", pg: "287–290، 297" },
    { id: "c7t2", title: "السوابق المكونة للركن المادي بحسب مصدرها", cols: ["وجه المقارنة", "الدول", "المنظمات الدولية", "القضاء الدولي", "فاعلون دوليون آخرون"], rows: [
      ["صور السوابق", "أعمال الأشخاص المختصين بتمثيلها، وتصرفات أجهزتها الأخرى: التشريعات الداخلية وأحكام المحاكم الداخلية", "ممارساتها الداخلية، وقراراتها، ومعاهداتها وممارساتها مع غيرها", "الأحكام القضائية والآراء الاستشارية للمحاكم الدولية الدائمة والتحكيم الدولي", "سلوك المنظمات غير الحكومية والشركات متعددة الجنسيات والشعوب الخاضعة للاحتلال"],
      ["ضابط الاعتداد بها", "أعمال الممثلين بلا جدال؛ والتشريعات إذا تلاقت أحكامها، والأحكام الداخلية إذا تشابه مضمونها (الرأي الراجح)", "ولا سيما القرارات المتكررة من منظمات عالمية المتشابهة المضمون", "دورها أساسي من المسلم به", "ألا تلقى تصرفاتهم اعتراضًا من أشخاص القانون الدولي الرئيسيين"],
      ["أمثلة", "تشريعات الجنسية ومركز الأجانب؛ أحكام عدم تسليم المجرمين السياسيين", "التصويت في مجلس الأمن (نامبيا 1971)؛ أعراف حفظ السلام؛ اتفاقيات المقر", "المحكمة قاضي اختصاصها؛ سمو القانون الدولي العام على الداخلي", "تدخل اللجنة الدولية للصليب الأحمر؛ حق الشعوب في تقرير مصائرها"]
    ], core: "الدول والمنظمات الدولية هم أشخاص القانون الدولي الرئيسيون الذين تصدر عنهم السوابق، وتشمل السوابق أيضًا أحكام القضاء الدولي وآراءه الاستشارية، وسلوك فاعلين دوليين آخرين بشرط ألا يلقى اعتراضًا من الأشخاص الرئيسيين.", pg: "291–294" },
    { id: "c7t3", title: "الركن المادي والركن المعنوي للعرف الدولي", cols: ["وجه المقارنة", "الركن المادي", "الركن المعنوي"], rows: [
      ["جوهره", "اعتياد التصرف على نهج معين: سوابق متكررة إيجابية أو سلبية", "الشعور بالإلزام بالتصرف على هذا النحو وليس غيره"],
      ["صلته بالعادة الدولية", "تشترك فيه العادة الدولية مع العرف", "لا يتوافر للعادة، وبه تتميز القاعدة العرفية عن العادات والمجاملات"],
      ["لدى من يُبحث عنه", "مختلف الأشخاص في العرف العالمي، وجميع المعنيين في الإقليمي والثنائي", "من أتوا السوابق ومن وافقوا عليها أو لم يعترضوا عليها"],
      ["ترتيب التكوّن", "يتكون أولًا في العرف الهادئ أو التقليدي", "يسبق استثناءً في العرف المتوحش (كتوصية الجمعية العامة)"],
      ["طبيعته في الإثبات", "مسألة مادية، وإثباته أيسر بكثير", "مسألة نفسية يصعب إقامة الدليل عليها"]
    ], core: "المادي سلوك متكرر يسهل إثباته لأنه مسألة مادية، والمعنوي شعور بالإلزام يصعب إثباته لأنه مسألة نفسية؛ ولا يقوم العرف إلا باجتماعهما، والركنان متداخلان في التكوين والإثبات.", pg: "285–286، 290–301" }
  ],
